import{_ as e,o as a,c as d,ao as o}from"./chunks/framework.CuAWL7bJ.js";const y=JSON.parse('{"title":"Dependent Slabs","description":"","frontmatter":{},"headers":[],"relativePath":"dependent-slabs.md","filePath":"dependent-slabs.md","lastUpdated":null}'),i={name:"dependent-slabs.md"};function n(l,t,r,s,c,g){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="Dependent-Slabs" tabindex="-1">Dependent Slabs <a class="header-anchor" href="#Dependent-Slabs" aria-label="Permalink to &quot;Dependent Slabs {#Dependent-Slabs}&quot;">​</a></h1><p>Dependent slab support is intended for sticky variable-selection samplers where the active coefficients have a joint Gaussian slab prior. Users should normally construct a model prior, a Gaussian slab prior, and an <code>AggregateSticky</code> strategy with a <code>GridThinningStrategy</code> inner clock.</p><h2 id="Support-Matrix" tabindex="-1">Support Matrix <a class="header-anchor" href="#Support-Matrix" aria-label="Permalink to &quot;Support Matrix {#Support-Matrix}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Dynamics</th><th style="text-align:right;">Aggregate sticky support</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>ZigZag</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Coordinate boundary velocities are sampled from the standard ZigZag law.</td></tr><tr><td style="text-align:right;"><code>BouncyParticle</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Gaussian boundary velocities use the reference velocity marginal.</td></tr><tr><td style="text-align:right;"><code>Boomerang</code> and <code>AdaptiveBoomerang</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Dense, diagonal, and low-rank Boomerang covariance representations use conditional Gaussian boundary velocities.</td></tr><tr><td style="text-align:right;">Diagonal-preconditioned <code>ZigZag</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Coordinate boundary velocities are scaled by the diagonal preconditioner.</td></tr><tr><td style="text-align:right;">Dense-preconditioned <code>ZigZag</code></td><td style="text-align:right;">no</td><td style="text-align:right;">A dense coordinate boundary law is not implemented.</td></tr><tr><td style="text-align:right;">Preconditioned <code>BouncyParticle</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Identity, diagonal, and dense preconditioners are supported.</td></tr><tr><td style="text-align:right;">Preconditioned <code>Boomerang</code> and <code>AdaptiveBoomerang</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Boundary velocities use the preconditioned Gaussian velocity covariance implied by the current preconditioner and Boomerang covariance.</td></tr></tbody></table><p>The supported aggregate clocks are:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Clock</th><th style="text-align:right;">Supported dynamics</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>SummedRateClock</code></td><td style="text-align:right;">all supported <code>AggregateSticky</code> dynamics</td><td style="text-align:right;">Exact by numerical integration for time-varying rates.</td></tr><tr><td style="text-align:right;"><code>LinearGaussianAggregateClock</code></td><td style="text-align:right;"><code>ZigZag</code>, <code>BouncyParticle</code>, diagonal-preconditioned <code>ZigZag</code>, preconditioned <code>BouncyParticle</code></td><td style="text-align:right;">Falls back to <code>SummedRateClock</code> for Boomerang-family flows.</td></tr><tr><td style="text-align:right;"><code>ExponentialSumAggregateClock</code></td><td style="text-align:right;">global-logscale slab clocks with linear dynamics</td><td style="text-align:right;">Falls back to <code>SummedRateClock</code> for Boomerang-family flows.</td></tr><tr><td style="text-align:right;"><code>ChebyshevResidualAggregateClock</code></td><td style="text-align:right;"><code>ZigZag</code>, <code>BouncyParticle</code> with global-logscale exchangeable slabs</td><td style="text-align:right;">Experimental and intentionally unexported.</td></tr><tr><td style="text-align:right;"><code>FourierResidualAggregateClock</code></td><td style="text-align:right;">Boomerang-family flows with fixed-covariance or global-logscale Gaussian slabs</td><td style="text-align:right;">Experimental and intentionally unexported.</td></tr></tbody></table><p>The public, user-facing constructors are the prior and slab types such as <code>BernoulliModelPrior</code>, <code>BetaBernoulliModelPrior</code>, <code>ExchangeableModelSizePrior</code>, <code>DenseGaussianSlab</code>, <code>IndependentZeroMeanGaussianSlab</code>, <code>IndependentZeroMeanLogscaleGaussianSlab</code>, <code>ExchangeableGaussianSlab</code>, <code>ZeroMeanExchangeableGaussianSlab</code>, and <code>GlobalLogscaleExchangeableGaussianSlab</code>.</p>',7)])])}const p=e(i,[["render",n]]);export{y as __pageData,p as default};
